'use client';

import { useId, useState } from 'react';

import { useAutoplay } from '@/registry/ndeko/hooks/use-autoplay';
import { useKeptHeight } from '@/registry/ndeko/hooks/use-kept-height';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { PRESS_LEAD_MS, usePress } from '@/registry/ndeko/lib/demonstration';
import { UsersIcon } from '@/registry/ndeko/lib/icons';

import { GROUPS, SECTION, type Group } from './data';
import { MemberRow } from './member-row';

const FIRST_SHOWN_ID = 'ben';

const SECOND_SHOWN_ID = 'rosa';

const RESTING_OPEN = [FIRST_SHOWN_ID];

const NONE_OPEN: string[] = [];

const READ_MS = 3600;

/** `null` until someone opens a row: all closed while the demonstration plays, one open under reduced motion. */
type OpenIds = string[] | null;

function openIdsOf(state: OpenIds, shouldReduceMotion: boolean) {
  if (state !== null) {
    return state;
  }
  if (shouldReduceMotion) {
    return RESTING_OPEN;
  }
  return NONE_OPEN;
}

function withToggled(ids: readonly string[], id: string, isOpen: boolean) {
  const others = ids.filter((candidate) => candidate !== id);
  if (isOpen) {
    return [...others, id];
  }
  return others;
}

function peopleWordOf(count: number) {
  if (count === 1) {
    return '1 person';
  }
  return `${count} people`;
}

type TeamGroupProps = {
  group: Group;
  openIds: readonly string[];
  pressed: string | null;
  onToggle: (memberId: string) => void;
};

function TeamGroup({ group, openIds, pressed, onToggle }: TeamGroupProps) {
  const headingId = useId();
  const count = group.members.length;

  return (
    <section aria-labelledby={headingId} className='flex flex-col gap-2'>
      <h3
        id={headingId}
        className='flex items-baseline gap-2 px-3 text-[13px] font-medium'
      >
        {group.name}
        <span className='text-muted-foreground text-xs font-normal tabular-nums'>
          {peopleWordOf(count)}
        </span>
      </h3>
      <ul className='flex flex-col gap-1'>
        {group.members.map((member) => (
          <MemberRow
            key={member.id}
            member={member}
            isOpen={openIds.includes(member.id)}
            isPressed={pressed === member.id}
            onToggle={onToggle}
          />
        ))}
      </ul>
    </section>
  );
}

export default function TeamSections02() {
  const [state, setState] = useState<OpenIds>(null);
  const { pressed, press } = usePress<string>();
  const shouldReduceMotion = usePrefersReducedMotion();
  const openIds = openIdsOf(state, shouldReduceMotion);

  function setOpen(id: string, isOpen: boolean) {
    const next = withToggled(openIds, id, isOpen);
    setState(next);
  }

  function toggle(id: string) {
    const isOpen = openIds.includes(id);
    setOpen(id, !isOpen);
  }

  const steps = [
    { after: 2200, run: () => press(FIRST_SHOWN_ID) },
    { after: PRESS_LEAD_MS, run: () => setOpen(FIRST_SHOWN_ID, true) },
    { after: READ_MS, run: () => press(FIRST_SHOWN_ID) },
    { after: PRESS_LEAD_MS, run: () => setOpen(FIRST_SHOWN_ID, false) },
    { after: 1200, run: () => press(SECOND_SHOWN_ID) },
    { after: PRESS_LEAD_MS, run: () => setOpen(SECOND_SHOWN_ID, true) },
    { after: READ_MS, run: () => press(SECOND_SHOWN_ID) },
    { after: PRESS_LEAD_MS, run: () => setOpen(SECOND_SHOWN_ID, false) },
  ];
  const { ref } = useAutoplay<HTMLElement>(steps, {
    loopAfter: 2400,
    onReset: () => setState(null),
  });
  useKeptHeight(ref);

  return (
    <section ref={ref} className='@container min-h-[56rem]'>
      <div className='mx-auto grid max-w-6xl gap-10 px-4 py-16 @2xl:px-6 @2xl:py-24 @4xl:grid-cols-[minmax(0,2fr)_minmax(0,3fr)] @4xl:gap-16 @5xl:px-8'>
        <header className='flex max-w-xl flex-col gap-3 self-start'>
          <p className='text-primary-ink flex items-center gap-1.5 text-[13px] font-medium'>
            <UsersIcon className='size-4' />
            {SECTION.label}
          </p>
          <h2 className='text-2xl font-semibold text-balance @2xl:text-3xl'>
            {SECTION.title}
          </h2>
          <p className='text-muted-foreground text-base text-pretty'>
            {SECTION.lead}
          </p>
        </header>
        <div className='flex flex-col gap-8'>
          {GROUPS.map((group) => (
            <TeamGroup
              key={group.id}
              group={group}
              openIds={openIds}
              pressed={pressed}
              onToggle={toggle}
            />
          ))}
        </div>
      </div>
    </section>
  );
}

'use client';

import { useId } from 'react';

import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import {
  ChevronDownIcon,
  GithubIcon,
  LinkedinBrandIcon,
  MapPinIcon,
  TwitterXIcon,
  type Icon,
} from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Avatar } from '@/registry/ndeko/ui/avatar';
import { Button } from '@/registry/ndeko/ui/button';
import { Fold } from '@/registry/ndeko/ui/chat-motion';

import type { Member, SocialKind } from './data';

const SOCIAL_ICONS: Record<SocialKind, Icon> = {
  linkedin: LinkedinBrandIcon,
  x: TwitterXIcon,
  github: GithubIcon,
};

const SOCIAL_NAMES: Record<SocialKind, string> = {
  linkedin: 'LinkedIn',
  x: 'X',
  github: 'GitHub',
};

function surfaceOf(isOpen: boolean) {
  if (isOpen) {
    return 'bg-card ring-border shadow-[0_1px_2px_rgb(0_0_0/0.04)] dark:bg-foreground/[0.04]';
  }
  return 'ring-transparent';
}

function chevronTurnOf(isOpen: boolean) {
  if (isOpen) {
    return 'rotate-180';
  }
  return 'rotate-0';
}

type MemberRowProps = {
  member: Member;
  isOpen: boolean;
  isPressed: boolean;
  onToggle: (memberId: string) => void;
};

export function MemberRow({
  member,
  isOpen,
  isPressed,
  onToggle,
}: MemberRowProps) {
  const bioId = useId();

  return (
    <li
      className={cn(
        'hairline-ring rounded-xl transition-[background-color,box-shadow] duration-200 ease-(--ease-out-strong)',
        surfaceOf(isOpen)
      )}
    >
      <button
        type='button'
        aria-expanded={isOpen}
        aria-controls={bioId}
        onClick={() => onToggle(member.id)}
        className={cn(
          'hover:bg-foreground/[0.03] focus-visible:ring-ring/25 flex w-full cursor-pointer items-center gap-3 rounded-xl px-3 py-2.5 text-start transition-[background-color,scale] duration-150 ease-(--ease-out-strong) outline-none focus-visible:ring-[3px]',
          pressedQuietOf(isPressed)
        )}
      >
        <Avatar seed={member.name} className='size-9' />
        <span className='flex min-w-0 flex-1 flex-col'>
          <span className='truncate text-sm font-medium'>{member.name}</span>
          <span className='text-muted-foreground truncate text-[13px]'>
            {member.role}
          </span>
        </span>
        <span className='text-muted-foreground hidden shrink-0 items-center gap-1 text-xs @xl:flex'>
          <MapPinIcon className='size-3.5' />
          {member.location}
        </span>
        <ChevronDownIcon
          className={cn(
            'text-muted-foreground size-4 shrink-0 transition-[rotate] duration-200 ease-(--ease-out-strong)',
            chevronTurnOf(isOpen)
          )}
        />
      </button>
      <Fold open={isOpen} id={bioId}>
        <div className='flex flex-col items-start gap-3 ps-[3.75rem] pe-4 pt-0.5 pb-4'>
          <p className='text-muted-foreground text-[13px] leading-5 text-pretty'>
            {member.bio}
          </p>
          <p className='text-muted-foreground flex items-center gap-1 text-xs @xl:hidden'>
            <MapPinIcon className='size-3.5' />
            {member.location}
          </p>
          <ul className='-mx-1.5 flex items-center gap-0.5'>
            {member.socials.map((social) => {
              const Glyph = SOCIAL_ICONS[social.kind];
              const label = `${member.name} on ${SOCIAL_NAMES[social.kind]}`;

              return (
                <li key={social.kind}>
                  <Button
                    variant='ghost'
                    size='icon-sm'
                    nativeButton={false}
                    aria-label={label}
                    render={<a href={social.href} />}
                    className='text-muted-foreground'
                  >
                    <Glyph />
                  </Button>
                </li>
              );
            })}
          </ul>
        </div>
      </Fold>
    </li>
  );
}

export type SocialKind = 'linkedin' | 'x' | 'github';

export type Social = {
  kind: SocialKind;
  href: string;
};

export type Member = {
  id: string;
  name: string;
  role: string;
  location: string;
  bio: string;
  socials: Social[];
};

export type Group = {
  id: string;
  name: string;
  members: Member[];
};

